import{_ as s,I as l,o as i,c as p,b6 as o,J as e,j as t,a as n}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"A/B 测试：用数据\\"做决策\\"","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/5-data/ab-testing.md","filePath":"zh-cn/appendix/5-data/ab-testing.md"}'),_={name:"zh-cn/appendix/5-data/ab-testing.md"};function d(h,a,g,b,u,c){const r=l("ABTestingDemo");return i(),p("div",null,[a[0]||(a[0]=o('<h1 id="a-b-测试-用数据-做决策" tabindex="-1">A/B 测试：用数据&quot;做决策&quot; <a class="header-anchor" href="#a-b-测试-用数据-做决策" aria-label="Permalink to “A/B 测试：用数据&quot;做决策&quot;”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">🎯 核心问题</p><p><strong>如何科学地验证产品改动的效果？</strong> 你可能经历过这样的场景：团队花了一个月做的新功能上线后，数据大涨！大家欢呼雀跃，可三周后数据又神秘地跌回了原貌。到底是因为新功能真的好，还是因为刚好赶上节假日流量大？A/B 测试解决的就是如何剔除外界的干扰噪音，让数据说出真相的问题。</p></div><hr><h2 id="_0-全景图-对抗-拍脑袋-的科学武器" tabindex="-1">0. 全景图：对抗&quot;拍脑袋&quot;的科学武器 <a class="header-anchor" href="#_0-全景图-对抗-拍脑袋-的科学武器" aria-label="Permalink to “0. 全景图：对抗&quot;拍脑袋&quot;的科学武器”">​</a></h2><p>在探讨具体技术之前，让我们先思考一下人类是如何做决策的。</p><p>当你面临两个按钮颜色设计：一个是沉稳的蓝色，一个是醒目的红色。通常，决策者会依赖于自身的经验、直觉、甚至是最高领导的偏好（业界戏称其为 <strong>HiPPO</strong> —— Highest Paid Person&#39;s Opinion，薪水最高者的意见）。</p><p>但用户的真实反馈往往远超我们的想象力。也许红色太刺眼反而导致转化率下降，也许蓝色不够引人注目……我们怎么能确信某种改动一定是更好的？</p><p>答案源自于经典的科学法则，这种法则和现代医学在验证新药时使用的手段如出一辙：<strong>对照实验</strong>。</p><div class="tip custom-block"><p class="custom-block-title">💡 A/B 测试的本质</p><p><strong>A/B 测试 = 对比 + 观察</strong> 这就如同医学研究中的&quot;双盲测试&quot;：</p><ul><li><strong>对照组（A组）</strong>：吃长得像药的淀粉片（看到老版本的页面）。</li><li><strong>实验组（B组）</strong>：吃正在研发的新药（看到新版本的页面）。 只有当实验组的治愈率（转化率）极其稳定且明显地高于对照组时，我们才能宣告新药（新改动）确实有效。</li></ul></div><hr><h2 id="_1-流量分配-切割平行宇宙" tabindex="-1">1. 流量分配：切割平行宇宙 <a class="header-anchor" href="#_1-流量分配-切割平行宇宙" aria-label="Permalink to “1. 流量分配：切割平行宇宙”">​</a></h2><p>做 A/B 测试的第一个铁律就是：<strong>同时、随机、隔离</strong>。</p><p>你绝对不能说：“前半个月所有的用户看蓝按钮，后半个月所有用户看红按钮。” 因为时间跨度带来了无数的变量——你完全无法知道后半个月转化率上涨是因为按钮是红色的，还是因为碰巧到了双十一旺季。</p><p>我们要做的是在同一时刻创造&quot;平行宇宙&quot;。每个进入网站的用户，系统都在底层立刻抛出了一枚数字硬币，决定他被分派到 A 宇宙，还是 B 宇宙。</p><p>你可以通过下面的演示，直观地观察系统是如何进行流量切割的：</p>',15)),e(r,{tab:"traffic"}),a[1]||(a[1]=o('<h3 id="_1-1-为什么随机分配如此重要" tabindex="-1">1.1 为什么随机分配如此重要？ <a class="header-anchor" href="#_1-1-为什么随机分配如此重要" aria-label="Permalink to “1.1 为什么随机分配如此重要？”">​</a></h3><p>只有百分之百的&quot;随机&quot;，才能最大程度抹平其他一切特征带来的差异。如果在足够大的样本量下进行了完美的随机切割，那么 A 组和 B 组的年轻用户比例、收入水平、地域分布原则上都会惊人的一致。</p><p>此时，如果二者的数据表现不同，那就排除了所有其他的干扰项和狡辩。唯一的不同，只能是因为你改了红色按钮。</p><hr><h2 id="_2-样本与检验-战胜假象的数学逻辑" tabindex="-1">2. 样本与检验：战胜假象的数学逻辑 <a class="header-anchor" href="#_2-样本与检验-战胜假象的数学逻辑" aria-label="Permalink to “2. 样本与检验：战胜假象的数学逻辑”">​</a></h2><p>好了，既然分了组，我们找 10 个用户分别看看结果不就行了？这就引出了 A/B 测试里最冷酷无情的数学法则：<strong>大数定律与样本量（Sample Size）</strong>。</p><p>想象你抛了 10 次硬币，结果 7 次正面、3 次反面，这能说明硬币被人做过手脚吗？显然不能，因为基数太小，7:3 纯粹就是波动、运气。但如果你抛了 10 万次，发现有 7 万次正面，那这时候就可以铁腕断言：硬币一定是偏心的。</p><p>同样，如果只是 100 个人测试，多一个人点击都会带来 1% 的暴涨暴跌。这就需要我们在实验开始前，通过公式计算必须凑满多少流量。</p>',8)),e(r,{tab:"calculator"}),a[2]||(a[2]=o('<h3 id="_2-1-统计学中的两大守护神" tabindex="-1">2.1 统计学中的两大守护神 <a class="header-anchor" href="#_2-1-统计学中的两大守护神" aria-label="Permalink to “2.1 统计学中的两大守护神”">​</a></h3><p>一旦跑满了这些流量条件，统计学就在我们寻找真相的旅程中布置了两尊门神：</p><ul><li><strong>统计功效 (Power, 通常要求 80%)</strong>：它代表如果你的新改动确实有效，你有多大的把握能把这个有效的效果侦测出来，而不是将其误认为是一种噪音放任自流。（防止说“无效”但其实“有效”的假阴性漏网之鱼）</li><li><strong>显著性水平 (P-Value, 通常要求小于 0.05)</strong>：也就是大家常说的“P&lt;0.05”。它的意思是，两组出现这样区别，如果是纯靠运气导致的概率是否小于 5%？要是运气占比连 5% 都不到，我们就会承认这就是<strong>统计显著</strong>(Significant)，这改动真的发挥了非凡的作用。（防止说“有效”但其实只是走运的假阳性）</li></ul><h2 id="_3-结果对决-真相审判" tabindex="-1">3. 结果对决：真相审判 <a class="header-anchor" href="#_3-结果对决-真相审判" aria-label="Permalink to “3. 结果对决：真相审判”">​</a></h2><p>收集完充足的数据后，我们需要通过下面这套专业的漏斗模型进行精确评判。对比结果不仅仅是一个简单的加减法，而是牵扯到置信度、正态分布计算的重头戏：</p>',5)),e(r,{tab:"results"}),a[3]||(a[3]=t("p",null,[n("当你看到页面上反馈了一个明确的"),t("strong",null,"“显著 ✅”"),n("时，那意味着我们可以向全公司自豪地宣布：抛弃我们主观幼稚的争论，立刻全量上线 B 方案！一切都有坚实的数学原理作为后盾。")],-1)),a[4]||(a[4]=t("hr",null,null,-1)),a[5]||(a[5]=t("h2",{id:"_4-幽暗的陷阱-分析中的误区",tabindex:"-1"},[n("4. 幽暗的陷阱：分析中的误区 "),t("a",{class:"header-anchor",href:"#_4-幽暗的陷阱-分析中的误区","aria-label":"Permalink to “4. 幽暗的陷阱：分析中的误区”"},"​")],-1)),a[6]||(a[6]=t("p",null,"虽然 A/B 测试本身是理性和科学的体现，但操作它的人却深受人性的弱点左右。人们往往只愿意看到自己期望的结果，这很容易让整个测试由于失真而陷入可怕的反噬：",-1)),e(r,{tab:"pitfalls"}),a[7]||(a[7]=o('<h3 id="_4-1-警惕-新奇效应" tabindex="-1">4.1 警惕“新奇效应” <a class="header-anchor" href="#_4-1-警惕-新奇效应" aria-label="Permalink to “4.1 警惕“新奇效应””">​</a></h3><p>当某样东西刚刚出现时，用户会因为纯粹的猎奇和新奇感，去点击你那个看起来乱七八糟的新按钮，这会让你的转化率在头三天呈现火箭式的拉升。</p><p>很多产品经理会在第三天果断拿着完美的数据停止实验并发放战报。但如果你耐心等到两周之后，你会发现用户的新鲜感一过，数据又阴暗地跌到了老版本的红线之下。这就是为什么实验的周期设置尤为关键，切勿被短期的虚高蒙蔽双眼。</p><hr><h2 id="_5-总结-培养向数据屈服的勇气" tabindex="-1">5. 总结：培养向数据屈服的勇气 <a class="header-anchor" href="#_5-总结-培养向数据屈服的勇气" aria-label="Permalink to “5. 总结：培养向数据屈服的勇气”">​</a></h2><p>总而言之，从“直觉式猜想”走向“A/B 测试”，对于任何一个团队来说都是一场巨大的心智蜕变。</p><ol><li><strong>提出谨慎假设</strong>：基于对用户的严谨观察，建立一条可以被量化的假说。</li><li><strong>切分平行世界</strong>：以纯粹的随机撕裂流量，剔除外在的噪音牵绊。</li><li><strong>接受样本洗礼</strong>：等待大数定律生效，用足量的时间和样本降低波动。</li><li><strong>进行数学审判</strong>：让 P 值来宣判方案的好坏，严格服从显著性的事实。</li></ol><p>作为软件的缔造者，最大的智慧莫过于——<strong>学会向事实屈服的勇气。我们不用再花费几个小时在会议室里为蓝色和红色吵得面红耳赤；只需静待两周，点击率会向我们证明，究竟谁才是最受用户拥簇的王者。</strong></p>',8))])}const T=s(_,[["render",d]]);export{P as __pageData,T as default};
